import { Pokemon } from "./enums/pokemon";
import { Species } from "./enums/pokemon-species";
import { Abilities } from "./enums/abilities";
import { Types } from "./enums/types";
import { Stat } from "./enums/stat";
import { PokemonForms } from "./enums/pokemon-form";
import { Fields } from "./enums/fields";
import { Decimal } from "decimal.js";
import { viabilityRatings } from "./texts/viabilityDecimals";

export class PokemonEntity {
    constructor(
        public readonly id: Pokemon,              // Unique Pokémon ID (Form-based)
        public readonly species: Species,        // Base Species Enum
        public readonly name: string,            // Pokémon Name
        public readonly baseExperience: number,  // Base experience yield
        public readonly abilities: Abilities[],  // List of abilities
        public readonly types: Types[],          // Pokémon Types
        public readonly baseHP: number, // Base Stats
        public readonly baseATK: number,
        public readonly baseDEF: number,
        public readonly baseSPATK: number,
        public readonly baseSPDEF: number,
        public readonly baseSPE: number,
        public readonly forms: PokemonForms[],   // Cosmetic Variations
        public readonly height: number,          // Pokémon height in decimeters
        public readonly weight: number,          // Pokémon weight in hectograms
        public readonly isDefault: boolean,       // Whether it's the default form
    ) {}

    /** Get base stat total (BST) */
    getBaseStatTotal(): number {
        return this.baseHP + this.baseATK + this.baseDEF + this.baseSPATK + this.baseSPDEF + this.baseSPE;
    }

    /** Check if Pokémon has a specific ability */
    hasAbility(ability: Abilities): boolean {
        return this.abilities.includes(ability);
    }

    /** Check if Pokémon is of a specific type */
    hasType(type: Types): boolean {
        return this.types.includes(type);
    }

    /** Get viability ratings for this Pokémon */
    getViabilityRatings(): Record<Fields, Decimal> {
        return viabilityRatings[this.species] || {};
    }
}

